<?php if(!defined('TELEDRIVE_INIT')){exit('Direct access not permitted');}class TelegramClient{private string $botToken;private string $apiUrl;private mixed $ch=null;public function __construct(?string $token=null){$this->botToken=$token?:TELEGRAM_BOT_TOKEN;$this->apiUrl="https://api.telegram.org/bot{$this->botToken}/";}public function __destruct(){if($this->ch&&is_resource($this->ch)){curl_close($this->ch);}}public function request(string $method,array $params=[],string $httpMethod='POST'):mixed{if(empty($this->botToken)){throw new Exception('Telegram Bot Token is not configured.');}$url=$this->apiUrl.$method;if(!$this->ch|| !is_resource($this->ch)){$this->ch=curl_init();curl_setopt($this->ch,CURLOPT_RETURNTRANSFER,true);curl_setopt($this->ch,CURLOPT_SSL_VERIFYPEER,true);curl_setopt($this->ch,CURLOPT_CONNECTTIMEOUT,10);curl_setopt($this->ch,CURLOPT_TIMEOUT,45);curl_setopt($this->ch,CURLOPT_TCP_KEEPALIVE,1);curl_setopt($this->ch,CURLOPT_FORBID_REUSE,0);}curl_setopt($this->ch,CURLOPT_URL,$url);if($httpMethod==='POST'){curl_setopt($this->ch,CURLOPT_POST,true);$hasFile=false;foreach($params as $param){if($param instanceof CURLFile){$hasFile=true;break;}}if($hasFile){curl_setopt($this->ch,CURLOPT_TIMEOUT,180);curl_setopt($this->ch,CURLOPT_POSTFIELDS,$params);}else{curl_setopt($this->ch,CURLOPT_TIMEOUT,45);curl_setopt($this->ch,CURLOPT_POSTFIELDS,http_build_query($params));}}else{curl_setopt($this->ch,CURLOPT_TIMEOUT,45);curl_setopt($this->ch,CURLOPT_HTTPGET,true);}$response=curl_exec($this->ch);$httpCode=curl_getinfo($this->ch,CURLINFO_HTTP_CODE);$curlError=curl_error($this->ch);if($response===false){throw new Exception("Telegram cURL Error: {$curlError}");}$result=json_decode($response,true);if(!$result|| !isset($result['ok'])){throw new Exception("Invalid response from Telegram API (HTTP {$httpCode}): {$response}");}if($result['ok']!==true){$desc=$result['description']??'Unknown Telegram error';throw new Exception("Telegram API Error ({$result['error_code']}): {$desc}");}return $result['result'];}public function sendMessage(string|int $chatId,string $text):array{return $this->request('sendMessage',['chat_id'=>$chatId,'text'=>$text,'parse_mode'=>'HTML']);}public function forwardMessage(string|int $toChatId,string|int $fromChatId,int $messageId):array{return $this->request('forwardMessage',['chat_id'=>$toChatId,'from_chat_id'=>$fromChatId,'message_id'=>$messageId]);}public function fetchMessagesBatch(string|int $targetChatId,string|int $sourceChatId,array $messageIds):array{if(empty($messageIds)||empty($this->botToken)){return[];}$fwdUrl=$this->apiUrl.'forwardMessage';$mh=curl_multi_init();$handles=[];foreach($messageIds as $id){$ch=curl_init();curl_setopt($ch,CURLOPT_URL,$fwdUrl);curl_setopt($ch,CURLOPT_RETURNTRANSFER,true);curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,true);curl_setopt($ch,CURLOPT_CONNECTTIMEOUT,8);curl_setopt($ch,CURLOPT_TIMEOUT,15);curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,http_build_query(['chat_id'=>$targetChatId,'from_chat_id'=>$sourceChatId,'message_id'=>$id]));curl_multi_add_handle($mh,$ch);$handles[$id]=$ch;}$running=null;do{curl_multi_exec($mh,$running);curl_multi_select($mh,0.2);}while($running>0);$messages=[];$delHandles=[];$delMh=curl_multi_init();$delUrl=$this->apiUrl.'deleteMessage';foreach($handles as $id=>$ch){$content=curl_multi_getcontent($ch);curl_multi_remove_handle($mh,$ch);if(PHP_VERSION_ID<80000){curl_close($ch);}$data=json_decode($content,true);if(!empty($data['ok'])&&isset($data['result']['message_id'])){$messages[$id]=$data['result'];$dch=curl_init();curl_setopt($dch,CURLOPT_URL,$delUrl);curl_setopt($dch,CURLOPT_RETURNTRANSFER,true);curl_setopt($dch,CURLOPT_SSL_VERIFYPEER,true);curl_setopt($dch,CURLOPT_CONNECTTIMEOUT,8);curl_setopt($dch,CURLOPT_TIMEOUT,15);curl_setopt($dch,CURLOPT_POST,true);curl_setopt($dch,CURLOPT_POSTFIELDS,http_build_query(['chat_id'=>$targetChatId,'message_id'=>$data['result']['message_id']]));curl_multi_add_handle($delMh,$dch);$delHandles[]=$dch;}}curl_multi_close($mh);if(!empty($delHandles)){$delRunning=null;do{curl_multi_exec($delMh,$delRunning);curl_multi_select($delMh,0.2);}while($delRunning>0);foreach($delHandles as $dch){curl_multi_remove_handle($delMh,$dch);if(PHP_VERSION_ID<80000){curl_close($dch);}}}curl_multi_close($delMh);return $messages;}public function editMessageText(string|int $chatId,int $messageId,string $text):array{return $this->request('editMessageText',['chat_id'=>$chatId,'message_id'=>$messageId,'text'=>$text,'parse_mode'=>'HTML']);}public function deleteMessage(string|int $chatId,int $messageId):bool{try{$res=$this->request('deleteMessage',['chat_id'=>$chatId,'message_id'=>$messageId]);return(bool)$res;}catch(Exception $e){error_log("Delete message error ($chatId / $messageId): ".$e->getMessage());return false;}}public function sendDocument(string|int $chatId,string $filePath,string $filename,string $caption=''):array{if(!file_exists($filePath)){throw new Exception("File not found for upload: {$filePath}");}$cFile=new CURLFile($filePath,mime_content_type($filePath)?:'application/octet-stream',$filename);$params=['chat_id'=>$chatId,'document'=>$cFile,];if(!empty($caption)){$params['caption']=$caption;}return $this->request('sendDocument',$params,'POST');}public function sendDocumentsBatch(string|int $chatId,array $documents):array{if(empty($documents)||empty($this->botToken)){return[];}$docUrl=$this->apiUrl.'sendDocument';$results=[];$windows=array_chunk($documents,3,true);foreach($windows as $window){$mh=curl_multi_init();$handles=[];foreach($window as $idx=>$doc){if(!file_exists($doc['path'])){continue;}$ch=curl_init();curl_setopt($ch,CURLOPT_URL,$docUrl);curl_setopt($ch,CURLOPT_RETURNTRANSFER,true);curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,true);curl_setopt($ch,CURLOPT_CONNECTTIMEOUT,15);curl_setopt($ch,CURLOPT_TIMEOUT,180);curl_setopt($ch,CURLOPT_POST,true);$cFile=new CURLFile($doc['path'],mime_content_type($doc['path'])?:'application/octet-stream',$doc['filename']);$params=['chat_id'=>$chatId,'document'=>$cFile,];if(!empty($doc['caption'])){$params['caption']=$doc['caption'];}curl_setopt($ch,CURLOPT_POSTFIELDS,$params);curl_multi_add_handle($mh,$ch);$handles[$idx]=$ch;}$running=null;do{curl_multi_exec($mh,$running);curl_multi_select($mh,0.1);}while($running>0);foreach($handles as $idx=>$ch){$content=curl_multi_getcontent($ch);$httpCode=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_multi_remove_handle($mh,$ch);if(PHP_VERSION_ID<80000){curl_close($ch);}$data=json_decode($content,true);if(!empty($data['ok'])&&isset($data['result']['document'])){$docInfo=$data['result']['document'];$results[$idx]=['message_id'=>(int)$data['result']['message_id'],'file_id'=>$docInfo['file_id'],'file_unique_id'=>$docInfo['file_unique_id']??'','file_name'=>$docInfo['file_name']??$documents[$idx]['filename'],'file_size'=>$docInfo['file_size']??filesize($documents[$idx]['path']),];}else{$desc=$data['description']??("HTTP ".$httpCode);throw new Exception("Batch Telegram upload error: {$desc}");}}curl_multi_close($mh);}ksort($results);return $results;}public function pinChatMessage(string|int $chatId,int $messageId,bool $disableNotification=true):bool{try{$res=$this->request('pinChatMessage',['chat_id'=>$chatId,'message_id'=>$messageId,'disable_notification'=>$disableNotification]);return(bool)$res;}catch(Exception $e){error_log("Pin message error: ".$e->getMessage());return false;}}public function unpinChatMessage(string|int $chatId,?int $messageId=null):bool{try{$params=['chat_id'=>$chatId];if($messageId!==null){$params['message_id']=$messageId;$this->request('unpinChatMessage',$params);}else{$this->request('unpinAllChatMessages',$params);}return true;}catch(Exception $e){error_log("Unpin error: ".$e->getMessage());return false;}}public function getChat(string|int $chatId):array{return $this->request('getChat',['chat_id'=>$chatId]);}public function getFile(string $fileId):array{return $this->request('getFile',['file_id'=>$fileId]);}public function getFileDownloadUrl(string $fileId):string{$fileInfo=$this->getFile($fileId);$filePath=$fileInfo['file_path'];return"https://api.telegram.org/file/bot{$this->botToken}/{$filePath}";}public function downloadFileContent(string $fileId):string{$url=$this->getFileDownloadUrl($fileId);$ch=curl_init();curl_setopt($ch,CURLOPT_URL,$url);curl_setopt($ch,CURLOPT_RETURNTRANSFER,true);curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,true);curl_setopt($ch,CURLOPT_CONNECTTIMEOUT,20);curl_setopt($ch,CURLOPT_TIMEOUT,120);$content=curl_exec($ch);$httpCode=curl_getinfo($ch,CURLINFO_HTTP_CODE);if(PHP_VERSION_ID<80000){curl_close($ch);}if($content===false||$httpCode!==200){throw new Exception("Failed to download file from Telegram (HTTP {$httpCode})");}return $content;}public function streamFileToOutput(string $fileId):bool{$maxAttempts=3;for($attempt=1;$attempt<=$maxAttempts;$attempt++){try{$url=$this->getFileDownloadUrl($fileId);$ch=curl_init();curl_setopt($ch,CURLOPT_URL,$url);curl_setopt($ch,CURLOPT_RETURNTRANSFER,false);curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,true);curl_setopt($ch,CURLOPT_CONNECTTIMEOUT,30);curl_setopt($ch,CURLOPT_TIMEOUT,0);curl_setopt($ch,CURLOPT_BUFFERSIZE,131072);curl_setopt($ch,CURLOPT_FOLLOWLOCATION,true);curl_setopt($ch,CURLOPT_WRITEFUNCTION,function($ch,$data){echo $data;if(ob_get_level()>0){ob_flush();}flush();return strlen($data);});$res=curl_exec($ch);$httpCode=curl_getinfo($ch,CURLINFO_HTTP_CODE);if(PHP_VERSION_ID<80000){curl_close($ch);}if($res!==false&&$httpCode===200){return true;}if($attempt<$maxAttempts){usleep(300000*$attempt);}}catch(Exception $e){error_log("Stream chunk error for {$fileId} (attempt {$attempt}): ".$e->getMessage());if($attempt<$maxAttempts){usleep(300000*$attempt);}}}return false;}}